// Hidden classes and Towers. Website lore built on the campaign owner's rules (towers from unclaimed Runes; Unique, Epic, Legendary).
module.exports = {
  towers: {
    "Human": { name: "The Milestone Spire", look: "A plain grey tower of stacked fieldstone that shows up overnight at a crossroads or in a ploughed field. It hums like a struck bell, and every floor looks a little more like somewhere you once lived.", floors: 10 },
    "Mysterious": { name: "The Fogglass Spire", look: "A tower you only find by getting lost, its walls half mirror and half mist. Stairs lead to rooms that were not there on the way up, and your reflection sometimes climbs a floor ahead of you.", floors: 20 },
    "Hell": { name: "The Ledger Spire", look: "A black iron tower wrapped in chains and brass plaques, each plaque a debt someone failed to pay. The air is dry and hot, and every door asks for a price before it opens.", floors: 30 },
    "Heaven": { name: "The Choir Spire", look: "A white tower of light so bright it has no visible edges, with singing that never stops. It feels peaceful, but every floor is judged, and the songs grow quieter when you fall short.", floors: 30 },
    "Chaos": { name: "The Shuffled Spire", look: "A tower that rearranges its own floors every hour, some upside down, some made of water, some ending in open sky. Nothing stays the same twice, including the rules of each trial.", floors: 40 },
    "Abyss": { name: "The Sunken Spire", look: "A tower that grows downward into the dark, so climbing it means descending. The pressure builds with every floor, and things that should not have eyes watch from the stairwells.", floors: 50 },
    "Inner Realm": { name: "The Heartwood Spire", look: "A living tower like the trunk of an impossible tree, its rings marking ages that never happened. It breathes slowly, and the deeper floors remember everyone who has climbed them.", floors: 60 },
    "Outer Realm": { name: "The Horizon Spire", look: "A tower that is always on the horizon no matter how far you walk, until suddenly you are inside it. Its floors are wide open plains under strange stars, linked by stairs that hang in the air.", floors: 70 },
    "Void": { name: "The Hollow Spire", look: "A tower of nothing, outlined only by the faint glow of the Runes it drains. Sound dies inside it, and climbers must bring their own light, their own air and their own sense of up.", floors: 80 },
    "Inner Void": { name: "The Unlit Spire", look: "A tower folded inside the Void itself, where even the absence of things is thinner. Climbers report forgetting the floor below as soon as they reach the next.", floors: 90 },
    "Primordial": { name: "The First Spire", look: "A tower of raw Law, built from the overflow of Runes too old to have names anyone remembers. The remains of progenitors drift through its halls as burning wind, still water and unmoving stone.", floors: 100 },
    // The other Towers of each realm (up to five per realm), keyed "<Realm> <n>". Named for one of the Runes that feeds them.
    "Human 2": { name: "The Scythe Spire", look: "A narrow tower of rusted farm iron, its walls hung with blades: scythes, axes, sickles, all still sharp. Gnome-sized doors open onto rooms that are too small to fight in and too efficient to leave, and every wound taken inside closes slower than it should." },
    "Human 3": { name: "The Heartbreak Spire", look: "A tower of grey chain and cold stone that splits in two halfway up and joins again at the top. Pale hands crawl along its walls, specters drift between its floors, and climbers say each room shows them someone they lost, then takes a little of their strength to let them pass." },
    "Human 4": { name: "The Adaptation Spire", look: "A tower that grows like a living thing, its lower floors bark and bone, its upper floors brass, glass, and bubbling vats. It learns: a trick that works on one floor is already countered on the next, and the parasites in its walls feed on anyone who stops changing." },
    "Human 5": { name: "The Reroll Spire", look: "A windy tower where the stairs sometimes run backward and the same floor can be walked twice with a different outcome. It smells of rain and cut grass, the west wind howls through its arches, and an hour inside can pass as a minute or a day." },
    "Mysterious 2": { name: "The Convergence Spire", look: "A tower where every road in the Mysterious Realm seems to end, built from masks stacked into walls. It moves a little each night, and its top floor hums with a faint echo of Infinatas, the creator, which is why the climbers who reach it are never quite the same." },
    "Mysterious 3": { name: "The Despair Spire", look: "A bronze tower drawn in straight, perfect lines that keep breaking down. Its machines misfire, its corpses still walk, and a heavy sorrow settles on everyone who climbs; the worst floors are the quiet ones, where nothing attacks and the despair does the work." },
    "Mysterious 4": { name: "The Tempo Spire", look: "A calm white tower where a slow drumbeat sets the pace of every fight. Keep to the rhythm and the floors are almost peaceful; break it and the guardians speed up until you cannot. Its walls are carved with the customs of a hundred vanished peoples." },
    "Mysterious 5": { name: "The Sylph Spire", look: "A spiralling tower of wind, open to the sky on every side, where the north and south winds wrestle around its stairs. Sylphs dart through its halls, old bones rattle in the gusts, and the top floor is the eye of a storm that never moves." },
    "Hell 2": { name: "The Apocalypse Spire", look: "A bone-white tower in the black ash of Hell, the only pale thing for miles. Its floors drift slowly out of line with each other, and every room tells the end of some world, nicked into the stone by those who watched it happen." },
    "Hell 3": { name: "The Knocking Spire", look: "A squat iron tower with no windows and one wall after another inside. Something knocks on every door from the other side; answer it and you face the floor's guardian. The last door is the end of a long legacy, and it has never been opened twice." },
    "Hell 4": { name: "The Pact Spire", look: "A tower of rotting green wood bound in iron and contract-paper, half overgrown and half man-made. Hidden archers watch from leaves that are not leaves, and every floor offers a pact: take it, and the climb gets easier and the price gets higher." },
    "Hell 5": { name: "The Revenant Spire", look: "A tower being worn away by a wind that only blows forward in time. Its lower floors are crumbling ruins, its middle floors are the present, and its upper floors are a future that has not happened yet. The dead it holds keep coming back, one floor later each time." },
    "Heaven 2": { name: "The Divergence Spire", look: "A tower of silver light with one long shadow that falls the wrong way. Its paths fork on every floor, each choice taking something away from the climber, and a soft sadness hangs over it, the grief of a Heaven that once went another way." },
    "Heaven 3": { name: "The Obsidian Spire", look: "A tower of black glass that burns white-hot inside, the one dark thing in Heaven. Its heat sharpens the body and boosts the spirit, its floors seem endless, and climbers who reach the top find the habits of a lifetime burned out of them." },
    "Heaven 4": { name: "The Planetary Spire", look: "A tower of horn and brass wound around a slowly turning orrery of planets. Every floor is built twice in case the first one fails, its guardians live joined to one another, and a calm numbness creeps over anyone who stays too long between the spheres." },
    "Heaven 5": { name: "The Shaman Spire", look: "A tower of painted hide and feathers that spins slowly on its base. Its spirit-guardians steal memories, cast the same spell twice, and mend whatever breaks; the climb tests the mind more than the body, and the top floor is a quiet fire with a shaman's empty seat." },
    "Chaos 2": { name: "The Crash Spire", look: "A tower that keeps falling down and standing back up. Its rooms are enchanted, then hollow, then full again; nothing in it can be identified twice, every floor has a fixed number of steps that changes when you count them, and somewhere above, something is always about to crash." },
    "Chaos 3": { name: "The Lich Spire", look: "A tower of dried flesh and old wrappings, scarred with the marks of every climber who failed. Liches, vampires, and mummies keep its floors, and at its heart beats one enormous heart that the Tower is still trying to keep alive." },
    "Chaos 4": { name: "The Recipe Spire", look: "A tower that smells of herbs, ointment, and spilled potions, its floors set out like a kitchen gone mad. Water spirits run through its pipes, every room is a recipe with one ingredient missing, and the air thins until climbers cook their way upward or turn back." },
    "Abyss 2": { name: "The Wish Spire", look: "A tower drowned in the Abyss, every floor filled to the ceiling with dark water that empties as you climb. A knight-guardian waits on each landing, the enemy of whoever approaches, and at the very bottom, which is its top, a single wish waits to be granted or turned against you." },
    "Abyss 3": { name: "The Isolation Spire", look: "A tower made of small stone cells, each for one climber only. Its guardians reach out of the dark to touch and rub, testing for fear, and those who give in to cowardice are sealed in alone. The party must climb apart and meet again at every boss floor." },
    "Abyss 4": { name: "The Paradox Spire", look: "A tower that is bigger inside than out, and smaller on every floor you climb. Its guardians are copies of the climbers, drawing strength from the originals, and the higher you go the more of yourself the Tower siphons away to feed them." },
    "Inner Realm 2": { name: "The Comet Spire", look: "A tower hit long ago by a falling star, which is still lodged in its crown and still burning. Its walls are carved with the first rules of the Inner Realm, small miracles happen on its stairs, and every boss floor ends in a long fall back down unless the climber holds on." },
    "Inner Realm 3": { name: "The Training Spire", look: "A tower of flesh and steel, built like an endless training hall. Its floors are drills: dexterity, strength, bracing, endurance. The guardians are tutors as much as foes, and a climber who stops learning finds the next floor much harder than the last." },
    "Inner Realm 4": { name: "The Transmutation Spire", look: "A tower in full bloom, its walls flowering, fruiting, and rotting into new shapes. Pollen turns one thing into another, the dead are raised and remade, and every attack the climbers make comes back at them a floor later, added together." },
    "Inner Realm 5": { name: "The Formation Spire", look: "A wide tower built in rigid ranks of stone, each floor wider than the one below it. Ghouls and ghasts guard it in perfect formation, repeating every move together, and the only way up is to break the line." },
    "Outer Realm 2": { name: "The Overdrive Spire", look: "A tower that never stops getting better: every floor is an improvement on the last, faster, hotter, louder. Fire runs in its veins, darts fly from its walls, and at its peak a faint, hungry echo of Inane waits to see how far a climber will push before it breaks." },
    "Outer Realm 3": { name: "The Shield Spire", look: "A tower covered in countless tiny overlapping plates, like a shield made of grains of sand. It grades every climber on each floor and only lets the toughest through, and the corpses of those who failed hold up its lower walls." },
    "Outer Realm 4": { name: "The Obsession Spire", look: "A tower of screws, gears, and skulls, all turning, that hums at the edge of hearing. It feeds on stress and obsession: the more a climber needs to reach the top, the stronger its guardians grow, and on some floors magic simply stops." },
    "Outer Realm 5": { name: "The Wendigo Spire", look: "A frozen tower lashed by endless hail, where a hungry wendigo stalks the stairs. Words spoken inside come undone into nonsense, some floors skip forward without warning, and the only sound that carries is a child's voice singing somewhere above." },
    "Void 2": { name: "The Banshee Spire", look: "A tower of thin grey light, finely tuned like an instrument, that hums one note in the silence of the Void. Banshees and wraiths keep its floors, wailing the names of famous climbers who never came back, and its top floor holds a small, perfect model of a whole world." },
    "Void 3": { name: "The Reality Spire", look: "A tower of ice, the most solid thing in the Void. Inside, reality turns on each floor, and climbers must see in a dark that has no source and speak mind to mind, because sound does not carry. Those who reach the top come back immune to things they cannot name." },
    "Inner Void 2": { name: "The Magnetic Spire", look: "A tower of iron filings held in shape by a pull with no source, assembling and falling apart as you climb. Lost blades, battle axes, and daggers drift toward it from across the Inner Void, and every promise made inside it turns out to be false." },
    "Inner Void 3": { name: "The Nightwalker Spire", look: "A tower lit only by the edges of drawn sabers. Nightwalkers and the summoned dead stalk its floors, every move inside must be exact, and the smallest mistake is punished with failure that cannot be undone." },
    "Inner Void 4": { name: "The Worship Spire", look: "A tower that beats like a heart, slowly, each pulse stretching the floors a little longer. Pilgrims of a forgotten faith still climb it in prayer, hope and blight grow side by side on its walls, and a blessing taken here can turn on its holder." },
    "Inner Void 5": { name: "The Servitude Spire", look: "A tower of humming, crackling stone, kept steady by the hopping undead who serve it. Every floor demands service before it lets you pass, and a small boy sits on the top step, waiting for someone to take over his job." },
    "Primordial 2": { name: "The Anchor Spire", look: "A tower chained to the bottom of the Primordial by an anchor the size of a mountain, its stones bleeding Law into the east wind. Inside lie the scraps of god-specific Runes that never found their god, wasted power that the Tower keeps for itself." },
    "Primordial 3": { name: "The Potential Spire", look: "A tower of raw metal and breaking stone, every floor a trial of what a climber could become. Glaive-bearing guardians test body, spirit, and ki together, and the walls crack open to show the shape of the climber at the top." },
    "Primordial 4": { name: "The Fusion Spire", look: "A tower ringed by bands of light that shorten as you climb, where things are fused together and taken apart. Its lowest floors are pools of first water to bathe in before the ascent; its highest fuse the climber with whatever they carried up." },
  },
  classes: [
    // ---------------- EPIC (2 per basic class, job change from level 5) ----------------
    { n: "Keeper of the Clay Giant", tier: "Epic", base: "Artificer", tower: "Human", unlock: "On floor 10 of the Milestone Spire a cracked clay guardian stands with a blank tablet in its mouth; repair it with your own tools and write a name on the tablet instead of destroying it. It follows you out.", secret: "The job only triggers if you have built at least 50 constructs or mechanisms of any kind before entering, and you never let the guardian drop to 0 hit points.", notice: "[Hidden job change. A name has been written. The clay remembers its maker.]", blurb: "Like the old tales of clay giants woken by a word on the tongue, this Artificer stops building gadgets and pours everything into one great body that grows with its maker.", requires: "Artificer level 5; Engineering profession level 3", features: [[5, "Skill: Name on the Tongue", "You build a Medium clay golem with hit points equal to five times your Artificer level that uses your proficiency bonus to attack (1d10 + your Intelligence modifier bludgeoning). It acts on your turn and Dodges unless you spend a bonus action to command it."], [9, "Skill: Graded Clay", "Rebuilding the golem with a higher grade material adds that material's Potency to its damage rolls and gives it +1 AC."], [13, "Ultimate: Giant Awakens", "Once per long rest, the golem grows to Large for 1 minute, gains temporary hit points equal to your Artificer level times 3, and its attacks deal an extra 2d8 damage."]], evolves: "At level 15, if the golem has fought beside you in 100 battles, it can be rebuilt as a Huge walking fortress you can ride inside.", cost: "Erase the word on its tongue and it falls apart; anyone who learns the word can unmake it." },
    { n: "Brass Siege-Lord", tier: "Epic", base: "Artificer", tower: "Hell", unlock: "The Ledger Spire's 15th floor is a devil's fortress with a one hour timer; breach its gate using only machines you built inside the tower from parts you salvaged there.", secret: "You must breach without any spell of 3rd level or higher, and no ally may land the final blow on the gate.", notice: "[Fortress breached. Hidden job unlocked: Brass Siege-Lord. The walls of the world feel thinner.]", blurb: "An Artificer who builds big, slow, devastating war engines meant to break gates, walls and armies.", requires: "Artificer level 5; Engineering profession level 3", features: [[5, "Skill: Deploy Battery", "As an action you deploy a Large siege engine. Once per turn it fires a ranged spell attack (range 120 feet) for 3d8 force damage, double against objects and structures."], [9, "Skill: Gatebreaker Round", "Once per short rest, the engine fires a round whose hit ignores the target's AC reduction."], [13, "Ultimate: Rain of Brass", "Once per long rest, the engine bombards a 20 foot radius within 300 feet: 6d8 force damage (Dexterity save for half), and any structure there is breached."]], evolves: "At level 15, after breaching the Ledger Spire's 30th floor gate alone, the engine gains legs and walks beside you.", cost: "The engine weighs 300 pounds and takes 10 minutes to set up or pack away." },

    { n: "Mountain That Walks", tier: "Epic", base: "Barbarian", tower: "Human", unlock: "Floor 8 of the Milestone Spire is the Avalanche Hall: stand in the path of falling stone for five rounds without taking a single step back.", secret: "You must have been reduced to 0 hit points at least three times in your life and stood back up each time without magical healing.", notice: "[You did not move. The mountain noticed. Hidden job: Mountain That Walks.]", blurb: "A Barbarian whose rage hardens instead of burning hot, like the stone giants of old tales who slept as hills: unmovable and nearly impossible to bring down.", requires: "Barbarian level 5; must have taken 100 damage in a single encounter", features: [[5, "Skill: Rooted", "While raging you cannot be pushed, pulled or knocked prone against your will."], [9, "Skill: Hillhide", "While raging you gain +2 AC and resistance to damage from falling and crushing."], [13, "Ultimate: The Mountain Stands", "Once per long rest, when you would drop to 0 hit points while raging, you drop to 1 instead, regain hit points equal to your Barbarian level, and your rage lasts 1 extra minute."]], evolves: "At level 15, after holding a doorway alone against a whole Tower floor, you can make your skin stone for a round once per rest, ignoring one hit completely.", cost: "Your speed drops by 10 feet while raging." },
    { n: "Warchief of the Wild Hunt", tier: "Epic", base: "Barbarian", tower: "Chaos", unlock: "Lead a band of at least three through a Shuffled Spire floor where each member faces a different trial, howling at its start, and bring every one of them back alive.", secret: "The band must ride, run or fly under a full moon at some point during the climb, and you must never retreat first.", notice: "[The horns are blowing. The Hunt has chosen a new leader.]", blurb: "A Barbarian whose rage spreads to everyone near them, like the riders of the wild hunt sweeping across the sky: a group becomes a pack.", requires: "Barbarian level 5; Charisma 13", features: [[5, "Skill: Hunting Horn", "When you start raging, up to three allies within 30 feet gain temporary hit points equal to your Barbarian level."], [9, "Skill: Pack Scent", "Allies within 10 feet of you add your rage damage bonus to their melee weapon damage."], [13, "Ultimate: Ride of the Hunt", "Once per long rest, every ally within 30 feet gains resistance to bludgeoning, piercing and slashing damage and +10 feet of speed for 1 minute, as though raging beside you."]], evolves: "At level 15, if your pack has slain a creature of a higher realm together, spectral riders join each Ride of the Hunt.", cost: "If an ally within 30 feet drops to 0 hit points, your rage ends at the end of your next turn." },

    { n: "Keener of the Grey Shore", tier: "Epic", base: "Bard", tower: "Mysterious", unlock: "On floor 12 of the Fogglass Spire a ghost waits on a grey beach for someone to mourn it; sing a lament you wrote yourself until it lets you pass.", secret: "The ghost only listens if you have attended the funerals of at least ten strangers, and the song must name it, though no one tells you its name.", notice: "[The dead are listening. Hidden job: Keener of the Grey Shore.]", blurb: "A Bard who learns the old keening songs sung over the dead, used to weaken the living and quiet the restless.", requires: "Bard level 5; Performance proficiency", features: [[5, "Skill: Mourning Verse", "When you spend Bardic Inspiration on an enemy, it subtracts the die from its next attack roll or saving throw."], [9, "Skill: Shoreward", "Undead and spirits within 30 feet of you have disadvantage on saves against your bard spells."], [13, "Ultimate: Song of the Grey Shore", "Once per long rest, undead within 60 feet make a Wisdom save or are turned for 1 minute, and creatures that die within 60 feet during that time cannot rise again."]], evolves: "At level 15, after singing a dead god's lament inside a Tower, the ghosts you calm can be asked one question each.", cost: "You cannot play joyful music; when you try, it comes out mournful." },
    { n: "Tongue of Treaties", tier: "Epic", base: "Bard", tower: "Heaven", unlock: "Win the Choir Spire's debate on floor 18 against a judge who cannot lie, convincing it to open a door it was ordered to keep shut.", secret: "You must have refused a god's contract offer three times before the debate; the judge already knows this.", notice: "[Three refusals counted. Your words now carry weight in Heaven.]", blurb: "A Bard who becomes a professional go-between for peoples, devils and gods, the one called in when two Fingers of a god cannot agree.", requires: "Bard level 5; Persuasion expertise", features: [[5, "Skill: Open Channel", "You can speak with and be understood by any creature that has a language, and you have advantage on Insight checks to read a speaker's intent."], [9, "Skill: Call for Parley", "As an action you declare a parley. Creatures within 60 feet that hear you make a Wisdom save or cannot attack for 1 minute unless attacked first."], [13, "Ultimate: Witness of Contracts", "While you witness a god's contract, you know if any clause is a trap, and the mortal can negotiate as though one rank higher."]], evolves: "At level 15, after brokering peace between two gods' contractors, you can witness a Pact and halve its repayment.", cost: "Breaking your own word gives you disadvantage on Charisma checks until your next long rest." },

    { n: "Saint of the Bleeding Field", tier: "Epic", base: "Cleric", tower: "Heaven", unlock: "Keep every wounded pilgrim alive across the Choir Spire's 'Long March' floor; if one dies, the floor resets.", secret: "Before the trial you must have healed 1,000 hit points to others in total, and you must finish the floor without healing yourself once.", notice: "[1,000 wounds closed. Heaven records a new saint.]", blurb: "A Cleric who becomes the saint of battlefields, healing closer to the fighting and faster than any other.", requires: "Cleric level 5; know at least three healing spells", features: [[5, "Skill: Quick Hands", "Once per short rest, you can cast a healing spell of 1st level or higher that takes an action as a bonus action instead."], [9, "Skill: No One Falls Here", "Allies within 10 feet of you automatically succeed on death saving throws."], [13, "Ultimate: Miracle of the Field", "Once per long rest, you restore hit points equal to five times your Cleric level, divided as you choose among creatures within 30 feet, and end one condition on each."]], evolves: "At level 15, after carrying the dying out of a Tower's top floor, you can return a creature dead for less than one minute once per long rest.", cost: "You cannot cast cantrips that deal damage." },
    { n: "Reliquary Bearer", tier: "Epic", base: "Cleric", tower: "Mysterious", unlock: "Recover a stolen saint's knucklebone from the Fogglass Spire's 14th floor and return it to its shrine without using its power once.", secret: "You must walk the whole way back barefoot, as pilgrims in old stories did.", notice: "[The relic is home. Its saint lends you a fragment of grace.]", blurb: "A Cleric who guards holy relics and draws on the power stored inside bones, cloth and old blood.", requires: "Cleric level 5; must carry a holy relic", features: [[5, "Skill: Bound Relic", "You attune to one relic as your holy symbol. Its grade's Potency is added to the damage and healing of your cleric spells."], [9, "Skill: Saint's Ward", "Allies within 15 feet of your relic have advantage on saves against being charmed or frightened."], [13, "Ultimate: Relic Burst", "Once per long rest, the relic releases its stored grace in a 20 foot radius: 6d10 radiant damage to enemies (Constitution save for half) and 3d10 healing to allies."]], evolves: "At level 15, if you bind a relic of Primary tier, it speaks with its saint's voice and gives one piece of advice per day.", cost: "If your relic is lost or broken you lose this class's features until you bind a new one over a week." },

    { n: "Green Man's Thornheart", tier: "Epic", base: "Druid", tower: "Human", unlock: "Replant the burned grove on floor 9 of the Milestone Spire and defend it for three days and nights.", secret: "You must not eat meat during the three days, and an acorn from the grove must still be in your pocket when you leave.", notice: "[The grove remembers you. Hidden job: Green Man's Thornheart.]", blurb: "Like the leaf-faced Green Man of old carvings, this Druid becomes the guardian of a single forest and carries it as armour and walls.", requires: "Druid level 5; Harvesting profession level 2", features: [[5, "Skill: Barkskin Mantle", "As a bonus action you grow bark armour for 10 minutes: +1 AC, and a creature that hits you with a melee attack takes 1d6 piercing damage. Once per short rest."], [9, "Skill: Hedge Wall", "As an action you raise a 30 foot line of thorn hedge that is difficult terrain and deals 2d8 piercing damage to anything moving through it."], [13, "Ultimate: Heart of the Grove", "Once per long rest, you plant a seed that becomes a sacred tree for 1 hour; allies within 30 feet regain 1d8 hit points at the start of each of their turns."]], evolves: "At level 15, if your grove survives a year, you can step into any tree and out of your grove's oldest one.", cost: "You must spend at least one night per month in a forest or lose this class's features until you do." },
    { n: "Coat-Thief of a Hundred Skins", tier: "Epic", base: "Druid", tower: "Chaos", unlock: "Pass through ten consecutive floors of the Shuffled Spire, each in a different wild shape, without returning to your true form.", secret: "Like a selkie whose coat was stolen, you must lose one form forever: the tower takes the first shape you ever learned.", notice: "[One coat surrendered. Ninety-nine to go.]", blurb: "Drawing on old tales of selkies and swan maidens whose power lived in a coat, this Druid collects beast skins and swaps between them mid-fight.", requires: "Druid level 5; Wild Shape", features: [[5, "Skill: Coat Swap", "You can change from one Wild Shape form to another as a bonus action without spending another use."], [9, "Skill: Borrowed Trait", "When you leave a form, you keep one of its senses or movement speeds for 1 minute."], [13, "Ultimate: Chimera Coat", "Once per long rest, you combine two beast forms you have worn, taking the higher hit points and both forms' attacks for 1 hour."]], evolves: "At level 15, once you have worn 100 different coats, you can wear the coat of a monstrosity.", cost: "If someone steals one of your coats (a trophy you keep for each form), you cannot take that form until you win it back." },

    { n: "Blade-Wedded", tier: "Epic", base: "Fighter", tower: "Hell", unlock: "Defeat the Ledger Spire's 20th floor duelist using only one weapon you have carried for at least a year, and speak your vows to it before the fight.", secret: "You must never have sold or swapped that weapon, and you must have named it.", notice: "[The vows are accepted. You and your blade are one.]", blurb: "A Fighter wedded to one weapon, like the sword-saints of legend who slept with their blades beside them.", requires: "Fighter level 5; one weapon used for a year", features: [[5, "Skill: Wedded Edge", "With your chosen weapon you gain +1 to attack rolls and score a critical hit on a 19 or 20."], [9, "Skill: Unparted", "You cannot be disarmed of your chosen weapon, and if it is a material weapon, its Potency counts as one grade higher."], [13, "Ultimate: Vow-Cut", "Once per short rest, when you hit with your chosen weapon, you deal an extra 4d10 damage of the weapon's type."]], evolves: "At level 15, after your weapon tastes the blood of a higher realm's champion, it awakens and gains a property of its own.", cost: "If your weapon is destroyed, you lose these features until you wed a new one through 30 days of training." },
    { n: "Last Shield of the Drowned Stair", tier: "Epic", base: "Fighter", tower: "Abyss", unlock: "Hold the stairs on the Sunken Spire's 25th floor, with allies behind you, against the rising tide of creatures for ten rounds.", secret: "Your allies must take less total damage than you during the stand.", notice: "[No one passed. Hidden job: Last Shield of the Drowned Stair.]", blurb: "A Fighter who leads from the front line, protecting the whole formation with shield and command.", requires: "Fighter level 5; proficiency with shields", features: [[5, "Skill: Cover the Line", "When an ally within 5 feet of you is hit, you can use your reaction to reduce the damage by your Fighter level."], [9, "Skill: Shieldwall", "Allies adjacent to you gain +1 AC while you hold a shield."], [13, "Ultimate: None Shall Pass", "Once per long rest, for 1 minute, you and allies within 10 feet cannot be frightened and gain resistance to the first hit each takes every round."]], evolves: "At level 15, after holding a Tower floor's boss at a door for a full minute, your shield can be planted as a wall that lasts 1 minute.", cost: "You cannot take the Dash or Disengage actions while you hold a shield." },

    { n: "Thousand-Strike Disciple", tier: "Epic", base: "Monk", tower: "Human", unlock: "Break one hundred wooden posts on floor 7 of the Milestone Spire within a single minute.", secret: "You must have trained the same strike one thousand times in a single day at some point before entering.", notice: "[One thousand strikes recorded. Your fists have outgrown your style.]", blurb: "A Monk whose speed turns a flurry into a storm of blows.", requires: "Monk level 5; Dexterity 16", features: [[5, "Skill: Blur of Fists", "When you use Flurry of Blows, you make three unarmed strikes instead of two."], [9, "Skill: Pressure Point", "Once per turn when you hit a creature three times, it makes a Constitution save or has its speed halved until the end of its next turn."], [13, "Ultimate: Thousand-Strike Storm", "Once per long rest, as an action you make ten unarmed strikes divided among creatures within 5 feet."]], evolves: "At level 15, after breaking a Tower floor's stone guardian barehanded, your strikes count as material of your highest grade weapon.", cost: "Using the ultimate with no ki left gives you a level of exhaustion." },
    { n: "Moon-in-the-Pond Ascetic", tier: "Epic", base: "Monk", tower: "Mysterious", unlock: "Meditate on the lake floor of the Fogglass Spire for a full day while its illusions try to break your focus; at dawn, catch the moon's reflection in your hand.", secret: "You must not have spoken a word for seven days before the meditation.", notice: "[You held the moon without touching it. Hidden job awakened.]", blurb: "A Monk who masters calm, like still water that holds the moon: every blow is turned aside and answered only when the enemy is open.", requires: "Monk level 5; Wisdom 16", features: [[5, "Skill: Still Surface", "You have advantage on saves against being charmed or frightened, and once per round you can deflect a melee attack as you would a missile."], [9, "Skill: Ripple Counter", "When a creature misses you with a melee attack, you can spend 1 ki to make an unarmed strike against it as a reaction."], [13, "Ultimate: Moon in the Pond", "Once per long rest, for 1 minute, damage you take from each hit is reduced by your Monk level."]], evolves: "At level 15, after a full day of silence inside a higher realm Tower, you can step into your own reflection and out of another within 60 feet.", cost: "You cannot use any weapon that weighs more than 3 pounds." },

    { n: "Lamplighter of the Long Night", tier: "Epic", base: "Paladin", tower: "Heaven", unlock: "Carry a lit lantern up all 30 floors of the Choir Spire without letting it go out.", secret: "The lantern must have been lit from a candle at a stranger's deathbed.", notice: "[The flame survived. You will be the light now.]", blurb: "A Paladin whose aura becomes a lantern in the dark, driving back fear and things that hide.", requires: "Paladin level 5; Aura of Protection or a sworn oath", features: [[5, "Skill: Guiding Light", "You shed bright light in a 30 foot radius at will. Invisible creatures in it are outlined and lose invisibility."], [9, "Skill: Lantern Aura", "Allies within your light have advantage on saves against being frightened."], [13, "Ultimate: Dawnflare", "Once per long rest, your light flares: undead and fiends within 30 feet take 6d8 radiant damage (Wisdom save for half)."]], evolves: "At level 15, after lighting a lamp at the top of a higher realm Tower, your light can be left behind as a lamp that wards a place for a year.", cost: "Your light cannot be hidden; you have disadvantage on Stealth checks while it is lit." },
    { n: "Headsman of the Red Ledger", tier: "Epic", base: "Paladin", tower: "Hell", unlock: "On the Ledger Spire's 22nd floor, carry out a sentence passed on a guilty creature, and refuse one passed on an innocent.", secret: "You must refuse the innocent sentence even when the devil offers to cure someone you love in return.", notice: "[Verdict accepted. Your name is written in red.]", blurb: "A Paladin who becomes the hand of judgement, punishing those who have truly done wrong.", requires: "Paladin level 5; Divine Smite", features: [[5, "Skill: Red Mark", "As a bonus action you mark a creature you have seen do harm. Your smites against it deal an extra 1d8 radiant damage."], [9, "Skill: No Escape", "A marked creature cannot become invisible to you, and its speed is reduced by 10 feet while within 30 feet of you."], [13, "Ultimate: Sentence Carried Out", "Once per long rest, if a marked creature is below half its hit points, your next smite against it deals maximum damage."]], evolves: "At level 15, after judging a god's contractor of Finger rank, your mark also reveals every crime the creature has committed.", cost: "If you mark an innocent creature, you lose Divine Smite until your next long rest." },

    { n: "Starpiercer", tier: "Epic", base: "Ranger", tower: "Mysterious", unlock: "Hit a target at the top of the Fogglass Spire from the ground floor, through all its illusions, with a single arrow.", secret: "The arrow must be one you fletched yourself, and you must loose it with your eyes closed.", notice: "[The arrow found its mark. Your eyes have been upgraded.]", blurb: "A Ranger who perfects the impossible shot, like the archers of legend who shot down false suns.", requires: "Ranger level 5; proficiency with longbow or crossbow", features: [[5, "Skill: Long Sight", "Your ranged weapon attacks ignore disadvantage at long range and ignore half cover."], [9, "Skill: Weak Spot", "Once per turn when you hit with a ranged weapon attack, you add 2d6 damage if you did not move this turn."], [13, "Ultimate: Sun-Shooter", "Once per long rest, you make a ranged attack with advantage at up to triple range; if it hits, it is a critical hit."]], evolves: "At level 15, after shooting something that flies above the clouds, your arrows can curve around corners.", cost: "Your passive Perception for creatures within 10 feet drops by 5." },
    { n: "Wyrmbane Huntsman", tier: "Epic", base: "Ranger", tower: "Abyss", unlock: "Track the Sunken Spire's floor 30 wyrm through three floors and slay it without it ever learning you were there.", secret: "As in the dragon-slayer tales, you must bathe in its blood afterwards; the class curse comes from that bath.", notice: "[You are soaked in wyrm blood. Monsters will know your scent now.]", blurb: "A Ranger who hunts the monsters other hunters run from, carrying the dragon-slayer's blessing and curse.", requires: "Ranger level 5; Survival proficiency", features: [[5, "Skill: Read the Beast", "When you hit a beast, dragon or monstrosity, you learn its resistances and vulnerabilities."], [9, "Skill: Trap Line", "Over 10 minutes you set traps in a 30 foot area. A creature entering it makes a Dexterity save or is restrained and takes 3d6 piercing damage."], [13, "Ultimate: Slayer's Blood", "Once per long rest, for 1 minute, you have resistance to damage from monsters and your weapon attacks against them deal an extra 2d10 damage."]], evolves: "At level 15, after slaying a true dragon, your skin hardens like scales (+1 AC) except for one spot the DM secretly picks.", cost: "Monsters smell the blood on you; you can never surprise a monstrosity or dragon." },

    { n: "Poison Master", tier: "Epic", base: "Rogue", tower: "Hell", unlock: "Reach floor 15 of the Ledger Spire and win the Poisoner's Banquet: brew a poison its devil host cannot identify, and survive the one he brews for you.", secret: "You must have survived being poisoned 100 times, and you must refuse the antidote the host offers at the end.", notice: "[Toxin resistance confirmed. Hidden job unlocked: Poison Master.]", blurb: "A Rogue whose assassin skills are honed into poison: every strike carries a dose, and every dose is chosen for the victim.", requires: "Rogue level 5; Alchemy profession level 3", features: [[5, "Skill: Coated Edge", "As a bonus action you coat a weapon with poison; the next three hits deal an extra 1d6 poison damage, and a target that takes Sneak Attack damage also makes a Constitution save or is poisoned until the end of its next turn."], [9, "Skill: Tailored Toxin", "When you coat a weapon, pick an effect: slowed (speed halved), weakened (disadvantage on Strength checks) or numbed (no reactions). Creatures resistant to poison damage do not resist your coatings."], [13, "Ultimate: Lethal Dose", "Once per long rest, when you hit with Sneak Attack, the target takes 6d6 poison damage at the start of each of its turns for 1 minute (Constitution save at the end of each turn ends it)."]], evolves: "At level 15, after poisoning a creature of a higher realm, you can brew a poison that works even on creatures immune to poison, once per week.", cost: "Your hands are stained by years of toxins; you have disadvantage on saves against your own poisons and healers can tell what you are." },
    { n: "Changeling of the Masked Court", tier: "Epic", base: "Rogue", tower: "Mysterious", unlock: "Pass through the Fogglass Spire's masked fey court on floor 16 by taking a courtier's place for a whole night, unnoticed.", secret: "Like a changeling left in a cradle, the courtier you replaced is still out there wearing your face; you must find them before the next full moon.", notice: "[No one noticed. Everyone is wearing someone. Hidden job: Changeling.]", blurb: "A Rogue who learns the fey trick of the changeling, stealing faces, voices and whole lives.", requires: "Rogue level 5; Deception expertise", features: [[5, "Skill: Borrowed Face", "Over 10 minutes you take on the appearance and voice of a creature you have studied for an hour. Checks to see through it have disadvantage."], [9, "Skill: Stolen Habits", "While disguised, you gain proficiency in one skill the copied creature has."], [13, "Ultimate: No One At All", "Once per long rest, every creature that sees you within the next hour forgets your face entirely."]], evolves: "At level 15, after fooling a god's contractor of Finger rank, you can copy one class feature of the creature you mimic for an hour.", cost: "Each time you keep a face for more than a day, you forget one small detail of your own life." },

    { n: "Overbrimming Chalice", tier: "Epic", base: "Sorcerer", tower: "Chaos", unlock: "Absorb the stray magic of the Shuffled Spire's 20th floor storm for a full hour without releasing it once.", secret: "Your hit points must fall below 10 during the hour, and you must still not release it.", notice: "[Capacity exceeded. Capacity increased. Hidden job: Overbrimming Chalice.]", blurb: "A Sorcerer who stores more power than their body should hold, and lets it spill out in bursts.", requires: "Sorcerer level 5; Constitution 14", features: [[5, "Skill: Reservoir", "You can store unused sorcery points past your maximum, up to your Constitution modifier; they fade after a long rest."], [9, "Skill: Spillover", "When you cast a spell using a slot of 3rd level or higher, creatures of your choice within 5 feet take force damage equal to the slot level."], [13, "Ultimate: Cup Runneth Over", "Once per long rest, you spend all stored sorcery points to deal 1d10 force damage per point in a 20 foot radius (Dexterity save for half)."]], evolves: "At level 15, after drinking the overflow of an unclaimed Rune at a Tower's top, your Reservoir doubles.", cost: "Each use of the ultimate deals you force damage equal to half the damage dealt." },
    { n: "Twin of the Drowned Mirror", tier: "Epic", base: "Sorcerer", tower: "Abyss", unlock: "Meet your own reflection at the bottom of the Sunken Spire's 35th floor, and agree to share your body with it instead of fighting it.", secret: "If you attack the reflection even once, the job is lost forever and the reflection keeps hunting you.", notice: "[Two souls detected in one vessel. Hidden job awakened.]", blurb: "A Sorcerer who shares their body with a second soul, a doppelganger that casts beside them.", requires: "Sorcerer level 5; Metamagic", features: [[5, "Skill: Second Voice", "Once per short rest, after you cast a cantrip as an action, you can cast a different cantrip as a bonus action."], [9, "Skill: Shared Mind", "You have advantage on saves against being charmed, as your twin notices the intrusion."], [13, "Ultimate: Two Casters", "Once per long rest, you cast two spells of 3rd level or lower on the same turn."]], evolves: "At level 15, if you and your twin agree on a name, it can step out as a separate body for 1 minute per long rest.", cost: "Your twin sometimes speaks out loud and has its own opinions." },

    { n: "Bailiff of the Brass Ledger", tier: "Epic", base: "Warlock", tower: "Hell", unlock: "Collect three overdue debts recorded on the Ledger Spire's 18th floor from creatures who do not want to pay.", secret: "One of the three debtors is you; you must collect from yourself first.", notice: "[Debts settled. The Ledger has hired you.]", blurb: "A Warlock who becomes a collector for Hell's ledgers, binding others to bargains and taking what is owed.", requires: "Warlock level 5; a patron or a god contract of Minor rank or higher", features: [[5, "Skill: Mark of Debt", "When a creature damages you, you can mark it; your next eldritch blast against it deals an extra 1d10 damage."], [9, "Skill: Collection", "When a marked creature drops to 0 hit points, you regain a spell slot."], [13, "Ultimate: Binding Bargain", "Once per long rest, a creature that agrees to a deal with you is bound; if it breaks the deal it takes 8d10 psychic damage."]], evolves: "At level 15, after collecting a debt from a devil, you can transfer one marked debt to another creature.", cost: "Every debt you mark must be collected; each you forgive costs you 1d10 hit points that cannot be healed until your next long rest." },
    { n: "Bottle-Djinn Broker", tier: "Epic", base: "Warlock", tower: "Abyss", unlock: "On the Sunken Spire's floors 40 to 42, three patrons sealed in bottles each offer you a deal; survive all three rooms and sign nothing, then take the bottles with you.", secret: "You must never uncork two bottles in the same day, or the patrons fight inside you.", notice: "[Three bottles acquired. Three voices whisper. Hidden job: Bottle-Djinn Broker.]", blurb: "A Warlock who carries bottled patrons like the djinn of old tales, taking scraps of power from several at once.", requires: "Warlock level 5; two contracts or pacts of any rank", features: [[5, "Skill: Uncork", "You learn one 1st level spell from another patron's list; it counts as a warlock spell."], [9, "Skill: Change Bottles", "After a long rest, you can switch one invocation for another tied to a different bottled patron."], [13, "Ultimate: Third Wish", "Once per long rest, when a creature casts a spell at you, you use your reaction to redirect it to another target within 30 feet as your patrons fight over you."]], evolves: "At level 15, after freeing one of the bottled patrons, it grants a single wish-like favour, then leaves forever.", cost: "Every other session one of your patrons asks a favour you must perform." },

    { n: "Wardstone Architect", tier: "Epic", base: "Wizard", tower: "Human", unlock: "Map and ward all ten floors of the Milestone Spire without leaving the tower.", secret: "None of your wards may harm another climber; the tower counts every injury.", notice: "[The tower is warded. It approves. Hidden job awakened.]", blurb: "A Wizard who builds magic into the world, raising standing stones and wards that fight for them.", requires: "Wizard level 5; Enchanting profession level 2", features: [[5, "Skill: Quick Ward", "You can cast glyph of warding in 1 minute instead of 1 hour, and its material cost is halved."], [9, "Skill: Chained Wards", "When one of your glyphs triggers, others within 30 feet can trigger at the same time."], [13, "Ultimate: Stone Circle", "Once per long rest, you raise a 30 foot ring of wardstones; you and allies inside have +1 AC and advantage on concentration checks for 1 hour."]], evolves: "At level 15, after warding a whole town for a year, your Stone Circle becomes permanent where you raise it.", cost: "Your wards are easy to sense; detect magic shows they were made by you." },
    { n: "Duelist of the Turned Spell", tier: "Epic", base: "Wizard", tower: "Chaos", unlock: "Defeat three wizards on the Shuffled Spire's 25th floor in spell duels, each under a different set of rules.", secret: "You must win at least one duel without casting a damaging spell.", notice: "[Three duels won. Your spells now answer back.]", blurb: "A Wizard trained for spell against spell, countering and turning enemy magic back on its caster.", requires: "Wizard level 5; know counterspell or shield", features: [[5, "Skill: Quick Counter", "You add your Intelligence modifier to ability checks made to counter or dispel magic."], [9, "Skill: Return to Sender", "When you counter a spell of 3rd level or lower, you can immediately cast that spell back at its caster using your own slot of the same level."], [13, "Ultimate: Duelist's Ring", "Once per long rest, for 1 minute, enemy spellcasters within 60 feet have disadvantage on concentration checks and on spell attack rolls against you."]], evolves: "At level 15, after turning a god's contractor's spell back on them, you can return spells of 5th level or lower.", cost: "Your duelling is famous; enemy casters target you first." },

    // ---------------- UNIQUE (12, one holder in the world at a time, from level 8) ----------------
    { n: "The Last Witness", tier: "Unique", base: "Any", tower: "Human", unlock: "Be the only survivor of the Milestone Spire's 10th floor, then tell each lost climber's story truthfully to their families.", secret: "You must not have caused any of the deaths, and you must lie to no one for the whole journey home.", notice: "[Unique class unlocked. Only one may witness. You are that one.]", blurb: "One of a kind: the keeper of the Law of Testimony, who sees and remembers everything that happens near them.", requires: "Character level 8; must have witnessed a death", features: [[8, "Skill: Perfect Recall", "You remember anything you have seen or heard in perfect detail."], [11, "Skill: Echo of Truth", "Once per long rest, you replay a scene from the last 24 hours within 60 feet as an illusion all can see."], [14, "Ultimate: Unforgettable", "Creatures cannot alter your memories, and once per long rest you can force a creature to remember an event it has forgotten."]], evolves: "At level 17, your testimony can be entered in any god's court and cannot be refuted.", cost: "You can never forget anything, including what you would rather not remember." },
    { n: "The Promise-Bound", tier: "Unique", base: "Any", tower: "Human", unlock: "Make a promise at the base of the Milestone Spire and keep it until you reach the top, even when breaking it would be easier.", secret: "Like the fey, whose word is law, the tower tests you with a floor where keeping your promise means losing a reward you need.", notice: "[Your word has become binding. Unique class: The Promise-Bound.]", blurb: "One of a kind: the bearer of the Law of Promise, whose words become binding forces, as fey bargains are.", requires: "Character level 8; have never broken a sworn oath", features: [[8, "Skill: Sworn Word", "When you swear something aloud, you have advantage on all checks to keep it until it is fulfilled."], [11, "Skill: Bound Ally", "Once per long rest, an ally who joins your promise adds your proficiency bonus to attack rolls while working towards it."], [14, "Ultimate: Unbreakable Vow", "Once per long rest, you swear to defend a creature; for 1 hour, half of any damage it takes is dealt to you instead."]], evolves: "At level 17, a promise someone makes to you binds them too: breaking it deals them 6d10 psychic damage.", cost: "If you break a promise, you lose this class until you redeem yourself, and someone else may claim it." },
    { n: "The Lantern of Wrong Turns", tier: "Unique", base: "Any", tower: "Mysterious", unlock: "Get completely lost on the Fogglass Spire's 20th floor and find your way back without help.", secret: "You must follow a will-o-wisp at least once and survive where it leads.", notice: "[You were lost, and now you are the light that leads others astray.]", blurb: "One of a kind: the bearer of the Law of Lost Ways, a living will-o-wisp who always knows the way out and can lead others astray.", requires: "Character level 8; Survival proficiency", features: [[8, "Skill: Always Found", "You always know the way back to the last place you rested, and you cannot become lost."], [11, "Skill: Wisp-Lure", "As an action, a creature within 60 feet makes a Wisdom save or moves in a random direction on its next turn."], [14, "Ultimate: Lost Road", "Once per long rest, you open a passage through fog to any place you have been in the same realm."]], evolves: "At level 17, your Lost Road can cross into the realm directly above or below the one you are in.", cost: "Maps you draw show nothing to anyone but you." },
    { n: "The Debt-Eater", tier: "Unique", base: "Any", tower: "Hell", unlock: "Pay off every debt chained to the Ledger Spire's 30th floor gate using your own blood, gold or memories.", secret: "At least one debt must be paid with a memory you treasure; the tower chooses which.", notice: "[Hidden condition met. The Debt-Eater looks at you.]", blurb: "One of a kind: the bearer of the Law of Debt, who feeds on what is owed and can cancel contracts.", requires: "Character level 8; have repaid a debt to a devil or god", features: [[8, "Skill: Debt Sight", "You can see any debt, pact or contract a creature has, including the parties to it."], [11, "Skill: Shared Burden", "Once per long rest, you take on another creature's curse, pact penalty or exhaustion level."], [14, "Ultimate: Swallow the Debt", "Once per long rest, you cancel a Pact or a Minor rank contract, gaining temporary hit points equal to 10 times its rank."]], evolves: "At level 17, you can swallow contracts of any rank below Finger, angering the god who held it.", cost: "Every debt you swallow becomes your own; a devil will one day collect." },
    { n: "The Unsung Saint", tier: "Unique", base: "Any", tower: "Heaven", unlock: "Climb the Choir Spire while letting another climber take the credit for every trial you pass.", secret: "Like the swan maiden who gave up her feathers, you must give away the reward of the 30th floor to someone who did nothing to earn it.", notice: "[No one will remember. Heaven will. Unique class unlocked.]", blurb: "One of a kind: the bearer of the Law of Sacrifice, who gives away their own strength so others can win.", requires: "Character level 8; must have given up a magic item or reward", features: [[8, "Skill: Give It Away", "As a bonus action, you give an ally within 30 feet one of your hit dice, which they spend immediately."], [11, "Skill: Selfless Opening", "When you forgo your attack, an ally within 30 feet can make one weapon attack as a reaction."], [14, "Ultimate: Final Gift", "Once per long rest, you drop to 1 hit point to fully restore an ally within 30 feet."]], evolves: "At level 17, your Final Gift can be given to an ally who died within the last minute.", cost: "No one will ever remember you as the hero; songs and records name someone else." },
    { n: "The Dice-Born", tier: "Unique", base: "Any", tower: "Chaos", unlock: "Win the Shuffled Spire's final game against the tower itself, a game of chance whose rules change every turn.", secret: "You must bet something you cannot get back, such as a year of life or a true name, and you must not cheat.", notice: "[Jackpot. Luck now belongs to you. Unique class: The Dice-Born.]", blurb: "One of a kind: the bearer of the Law of Odds, who bends luck like the trickster gamblers of old tales.", requires: "Character level 8; must have bet everything you own on a single roll", features: [[8, "Skill: Loaded", "Once per short rest, you can reroll any d20 rolled within 60 feet, yours or another creature's."], [11, "Skill: Double or Nothing", "When you roll damage, you can double it; on an odd roll your next attack has disadvantage."], [14, "Ultimate: House Wins", "Once per long rest, you set any single d20 result within 60 feet to a 1 or a 20."]], evolves: "At level 17, once per week you can make a creature reroll its death, re-rolling a killing blow.", cost: "Your luck always balances: each 20 you force brings a 1 to a roll the DM chooses later." },
    { n: "The Drowned Crown", tier: "Unique", base: "Any", tower: "Abyss", unlock: "Reach the deepest floor of the Sunken Spire and put on the crown resting there while the pressure tries to crush you.", secret: "The crown only accepts someone who has nearly drowned before; it can smell the old water in your lungs.", notice: "[The crown fits. The deep bows. Unique class awakened.]", blurb: "One of a kind: the bearer of the Law of Pressure, who can crush or lift anything by its weight.", requires: "Character level 8; must survive being underwater for 1 hour", features: [[8, "Skill: Weight of the Deep", "As an action, a creature within 60 feet makes a Strength save or is restrained and takes 2d10 bludgeoning damage."], [11, "Skill: Pressure Ward", "You ignore the effects of deep water and high pressure and gain +1 AC."], [14, "Ultimate: Abyssal Crush", "Once per long rest, every creature in a 30 foot radius makes a Strength save or takes 10d10 bludgeoning damage, half on a success."]], evolves: "At level 17, you can command the sea to rise or fall by 10 feet within a mile of you once per day.", cost: "On land, you always feel slightly too light; your speed is reduced by 5 feet." },
    { n: "The Threadcutter", tier: "Unique", base: "Any", tower: "Inner Realm", unlock: "On the Heartwood Spire's 40th floor, cut a thread binding you to someone you love, and survive their absence for the rest of the climb.", secret: "Like the spinner at the end of a life's thread, you must hold the shears for one full day before you are allowed to cut.", notice: "[A thread is cut. The shears are yours now.]", blurb: "One of a kind: the bearer of the Law of Severance, who cuts bonds, links and connections, like the fate-spinners of myth.", requires: "Character level 8; must have broken a bond of kinship or loyalty", features: [[8, "Skill: Cut the Line", "As an action, you end a charm, possession or telepathic link affecting a creature within 30 feet."], [11, "Skill: Severed", "Your weapon attacks break a creature's concentration automatically on a hit."], [14, "Ultimate: Final Cut", "Once per long rest, you sever a creature's link to its god or patron for 1 minute, so it cannot cast spells from that source."]], evolves: "At level 17, you can sever a contract permanently, with the god watching.", cost: "You can never form a new bond of friendship that lasts more than a year." },
    { n: "The Cartographer of Nowhere", tier: "Unique", base: "Any", tower: "Outer Realm", unlock: "Map every floor of the Horizon Spire before climbing it, using only a single sheet of paper.", secret: "Your map must include a floor that does not exist yet; the tower then builds it for you.", notice: "[The map is drawn. The world agrees with it. Unique class unlocked.]", blurb: "One of a kind: the bearer of the Law of Distance, who stretches or folds the space between two points.", requires: "Character level 8; Navigation profession level 4", features: [[8, "Skill: Short Step", "Your walking speed is doubled, and difficult terrain costs you no extra movement."], [11, "Skill: Stretched Path", "As an action, you make the distance between you and a creature within 60 feet three times longer for 1 minute."], [14, "Ultimate: Folded Map", "Once per long rest, you move yourself and up to six allies to any place you have mapped in the same realm."]], evolves: "At level 17, your Folded Map can reach any realm you have personally mapped.", cost: "Others get lost easily when following you." },
    { n: "The Silent Name", tier: "Unique", base: "Any", tower: "Void", unlock: "Reach the top of the Hollow Spire while letting the Void take your name; you climb out with no one remembering it.", secret: "As in the old tales where knowing a name gives power, the Void keeps your name; whoever learns it can command you once.", notice: "[Name deleted. Unique class: The Silent Name.]", blurb: "One of a kind: the bearer of the Law of Forgetting, who erases things from memory, including themselves.", requires: "Character level 8; must give up your name", features: [[8, "Skill: Unremembered", "Creatures forget your face 1 minute after you leave their sight."], [11, "Skill: Erase", "Once per short rest, a creature within 30 feet makes a Wisdom save or forgets the last minute."], [14, "Ultimate: Blank Slate", "Once per long rest, you erase a spell, rune or curse from a creature's memory for 24 hours."]], evolves: "At level 17, you can erase a creature from every memory in a town for one day.", cost: "Your friends must be reintroduced to you every morning." },
    { n: "The Hourless", tier: "Unique", base: "Any", tower: "Inner Void", unlock: "Stand still on the Unlit Spire's 90th floor while time stops around you, and wait long enough for it to start again.", secret: "You must not count the seconds; the moment you start counting, time never restarts for you and the trial fails.", notice: "[Time resumed. You did not. Unique class awakened.]", blurb: "One of a kind: the bearer of the Law of Pause, who freezes moments in place.", requires: "Character level 8; must have survived a time loop or stasis", features: [[8, "Skill: Freeze Frame", "As a reaction when an attack would hit you, you pause the moment and gain +2 AC against that attack."], [11, "Skill: Hold the Moment", "Once per short rest, a creature within 30 feet makes a Wisdom save or skips its next turn."], [14, "Ultimate: Stopped Clock", "Once per long rest, you take two turns in a row."]], evolves: "At level 17, your Stopped Clock can include one ally.", cost: "You age one year for every Stopped Clock you use." },
    { n: "The First Echo", tier: "Unique", base: "Any", tower: "Primordial", unlock: "On the First Spire's 100th floor, repeat the first words ever spoken there and hear them answered.", secret: "The first words were spoken by Infinatas; you must have heard them in a dream before, which most holders only realise afterwards.", notice: "[It has happened before. It will happen again. Unique class unlocked.]", blurb: "One of a kind: the bearer of the Law of Precedent, who repeats what has already happened.", requires: "Character level 8; must have seen an ancient ruin's first carving", features: [[8, "Skill: Repeat", "Once per short rest, you can repeat your last action as a bonus action."], [11, "Skill: Echo Strike", "When an ally hits a creature, you use your reaction to make that hit deal its damage again."], [14, "Ultimate: Again", "Once per long rest, you repeat an event from the last minute, such as a spell or attack, from its original source."]], evolves: "At level 17, your Again can repeat an event from the last hour.", cost: "You cannot do anything for the very first time; you must see it done once before." },

    // ---------------- LEGENDARY (follow a Rune's progenitor, from level 15) ----------------
    { n: "Ashborn Sovereign", tier: "Legendary", base: "Any", prog: "Ignis", tower: "Primordial", unlock: "Climb the First Spire to the hall where Ignis's remains still burn, and take up an Ignis Cinder from its body without flinching from the fire.", secret: "You must have burned every possession you own except your weapon before entering, as Ignis consumed everything it touched.", notice: "[The first flame recognises its heir. Legendary class: Ashborn Sovereign.]", blurb: "Follows Ignis, the hungry spirit of Fire whose corpse became the Fire Law: a mortal who carries a piece of the first flame, like the phoenix of legend.", requires: "Character level 15; a Primary piece of Ignis's remains", features: [[15, "Skill: Hunger of Ignis", "Your fire damage ignores resistance, and once per turn when you deal fire damage you regain hit points equal to half of it."], [17, "Skill: Children of Ignis", "Once per long rest, you call on Heat and Lava: a 30 foot radius becomes molten ground for 1 minute, dealing 6d10 fire damage to creatures that start their turn there."], [20, "Ultimate: Living Flame", "Once per long rest, you become living flame for 1 minute: you cannot be harmed by anything that can burn, and creatures that touch or hit you take 4d10 fire damage."]], evolves: "If you die while holding this class, you rise from your ashes once, then the class is lost forever.", cost: "Like Ignis, you hunger; you must burn something of value every day or take a level of exhaustion." },
    { n: "Ever-Flowing", tier: "Legendary", base: "Any", prog: "Undine", tower: "Outer Realm", unlock: "At the top of the Horizon Spire lies a pool that never holds the same shape twice; drink from it and claim the piece of Undine's remains at its bottom.", secret: "You must never have slept in the same bed twice in the last year, matching Undine's restlessness.", notice: "[Shape undefined. The water accepts you. Legendary class awakened.]", blurb: "Follows Undine, the restless spirit of Water: a mortal whose body flows like the water whose Law it became, like the selkies and river spirits of old tales.", requires: "Character level 15; a Primary piece of Undine's remains", features: [[15, "Skill: Flowing Body", "You can move through spaces as narrow as 1 inch, and once per turn you can halve the damage of a single hit."], [17, "Skill: Still the Waters", "Once per long rest, you call on Ice and Frost: creatures within 30 feet make a Constitution save or are restrained in ice for 1 minute."], [20, "Ultimate: Never the Same Shape", "Once per long rest, you become water for 1 minute, immune to nonmagical damage and able to move through any liquid at triple speed."]], evolves: "If you gather a second piece of Undine, you can become a flood that carries allies across a realm in a day.", cost: "You cannot stay in one place more than a day without growing restless; staying longer gives disadvantage on all checks." },
    { n: "Patient Mountain", tier: "Legendary", base: "Any", prog: "Gnome", tower: "Inner Void", unlock: "On the Unlit Spire's 90th floor, sit beside Gnome's resting remains for a year and a day, until it lets you take a piece of its stone.", secret: "Gnome rejects anyone who has ever struck in anger; you must have spent a year without starting a fight.", notice: "[Patience confirmed. The stone does not hurry. Legendary class unlocked.]", blurb: "Follows Gnome, the slow and patient spirit of Earth, father of Iron and Diamond.", requires: "Character level 15; a Primary piece of Gnome's remains", features: [[15, "Skill: Stone and Root", "You gain +2 AC and cannot be knocked prone; the ground within 10 feet of you is difficult terrain for enemies."], [17, "Skill: Rising Earth", "Once per short rest, you raise a 30 foot wall of stone or open a 20 foot pit within 60 feet."], [20, "Ultimate: Unmoving", "Once per long rest, you become stone for 1 minute: resistance to all damage and immunity to being moved or restrained."]], evolves: "If you reconcile with Diamond's heir or free Iron, Gnome's children answer your call once.", cost: "You act slowly; you always go last in initiative." },
    { n: "Four-Winds Wanderer", tier: "Legendary", base: "Any", prog: "Sylph", tower: "Void", unlock: "Reach the top of the Hollow Spire, where Sylph's last breath still blows through the empty halls, and catch it before it leaves.", secret: "Each of Sylph's four children must have touched you: a north gale, a west breeze, a south heat and an east storm, over one year.", notice: "[The wind has found someone who will not stay. Legendary class awakened.]", blurb: "Follows Sylph, the never-still spirit of Air, mother of the four winds: a mortal who moves like a voice on the wind.", requires: "Character level 15; a Primary piece of Sylph's remains", features: [[15, "Skill: Windborne", "You gain a flying speed equal to your walking speed and cannot be grappled."], [17, "Skill: Call of the Four Winds", "Once per short rest, you call Boreas (4d10 cold), Zephyrus (heal 4d10), Notus (4d10 fire) or Eurus (push 30 feet and 4d10 bludgeoning) on a target within 60 feet."], [20, "Ultimate: Vortex", "Once per long rest, you create a 40 foot whirlwind for 1 minute that pulls creatures towards its centre and deals 6d10 bludgeoning damage each turn."]], evolves: "If Boreas accepts you, you can challenge a god's contractor of Finger rank to a duel they cannot refuse.", cost: "You cannot sleep under a roof; doing so means no long rest." },
    { n: "Cagebreaker", tier: "Legendary", base: "Any", prog: "Iron", tower: "Mysterious", unlock: "At the top of the Fogglass Spire, where the spirit edges thin, stands a lock forged from a sliver of Iron's cage; break it and Iron speaks to you through the bars, the only link a mortal can make to a progenitor still alive.", secret: "You must have forged, broken and reforged the same iron weapon one hundred times; Iron only speaks to those who understand repetition.", notice: "[A voice through iron bars: Free me. Legendary class: Cagebreaker.]", blurb: "Follows Iron, Gnome's favourite child, strong and versatile and still trapped: a mortal who fights for his release.", requires: "Character level 15; a key fragment of Iron's cage", features: [[15, "Skill: Iron Will", "You are proficient with all weapons and armour, and any metal weapon you wield counts as one grade higher."], [17, "Skill: Edge of Steel", "As a bonus action, you reshape a weapon's edge: +2d6 damage or +1 AC while wielding it, chosen each turn."], [20, "Ultimate: Through the Bars", "Once per long rest, Iron's strength flows through you for 1 minute: your Strength becomes 26 and your attacks deal an extra 2d10 force damage."]], evolves: "If you ever free Iron, the class becomes the first Primary-tier Iron class of this age.", cost: "Iron's captors watch for anyone trying to free him; powerful beings hunt you." },
    { n: "Unshattered", tier: "Legendary", base: "Any", prog: "Diamond", tower: "Inner Realm", unlock: "Gather every shard of Diamond scattered across the Heartwood Spire's 60 floors and set them back together at the top.", secret: "Diamond was unwanted by its father; it only accepts someone who has been rejected by their own family or teacher.", notice: "[Shards assembled. You will not break. Legendary class awakened.]", blurb: "Follows Diamond, the strongest and most prestigious child of Gnome, broken to pieces long ago.", requires: "Character level 15; a Primary shard of Diamond's body", features: [[15, "Skill: True Hardness", "Once per short rest, you harden a part of your body to diamond and negate one hit entirely."], [17, "Skill: Refraction", "As a reaction, you blind a creature within 10 feet that attacks you (Constitution save)."], [20, "Ultimate: Unbreakable", "Once per long rest, for 1 minute, you cannot take damage from the same source more than once per round."]], evolves: "If you find what broke Diamond, you can carry its full shattered body as armour that never breaks.", cost: "Gnome's unwanted heir: those who follow Gnome refuse to aid you." },
    { n: "Deathless Heir", tier: "Legendary", base: "Any", prog: "First Lich", tower: "Void", unlock: "Find the First Lich's remains at the top of the Hollow Spire and win the debate it left behind: prove that a corpse and a spirit can still be bound.", secret: "You must have died once and come back, and you must have defeated 100 undead without ever being healed in those fights.", notice: "[Death is a status effect. Legendary class: Deathless Heir.]", blurb: "Follows the First Lich, the first mortal who carried their own body into undeath: a mortal who refuses to stay dead.", requires: "Character level 15; a piece of the First Lich's remains", features: [[15, "Skill: Unending", "Once per long rest, when you would die, you return to 1 hit point at the start of your next turn."], [17, "Skill: Ancient Servant", "You bind one of the First Lich's creations, a death knight or dullahan, which serves you with its full skill."], [20, "Ultimate: Lich's Bargain", "Character Death never costs you a stat permanently; the loss heals the next time you raise a corpse."]], evolves: "If you find a second piece of the First Lich, you can raise one fallen ally as a revenant who keeps all its skill.", cost: "The living sense death on you; animals flee and healing spells restore only half." }
  ]
};
